class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10 ** 9 + 7
        n = len(s)
        m = sum(1 for l in range(1, n) if s[l:] + s[:l] == t)
        a, b = (1, 0) if s == t else (0, 1)
        for _ in range(k):
            a, b = (m * a + (n - 1 - m) * b) % MOD, ((n - 1 - m) * a + (m - 1) * b) % MOD
        return a

