class Solution {
public:
    int numberOfWays(string s, string t, int k) {
        const long long MOD = 1e9 + 7;
        int n = s.size();
        long long m = 0;
        for (int l = 1; l < n; l++) if (s.substr(l) + s.substr(0, l) == t) m++;
        long long a = (s == t), b = 1 - a;
        while (k--) {
            long long na = (m * a + (n - 1 - m) % MOD * b) % MOD;
            long long nb = ((n - 1 - m) % MOD * a + (m - 1 + MOD) % MOD * b) % MOD;
            a = na; b = nb;
        }
        return a;
    }
};

