class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10 ** 9 + 7
        n = len(s)
        lps = [0] * n
        j = 0
        for i in range(1, n):
            while j and t[i] != t[j]: j = lps[j - 1]
            if t[i] == t[j]: j += 1
            lps[i] = j
        txt = s + s
        j = 0; m = 0
        for i, ch in enumerate(txt):
            while j and ch != t[j]: j = lps[j - 1]
            if ch == t[j]: j += 1
            if j == n:
                p = i - n + 1
                if 1 <= p <= n - 1: m += 1
                j = lps[j - 1]
        def mul(A, B):
            return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % MOD, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % MOD],
                    [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % MOD, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % MOD]]
        M = [[m % MOD, (n - 1 - m) % MOD], [(n - 1 - m) % MOD, (m - 1) % MOD]]
        R = [[1, 0], [0, 1]]
        p = k
        while p:
            if p & 1: R = mul(R, M)
            M = mul(M, M); p >>= 1
        a0 = 1 if s == t else 0
        return (R[0][0] * a0 + R[0][1] * (1 - a0)) % MOD

